    generate_completions_from_executable(bin/"tafas", "--completions")
  end

  def caveats
    <<~EOS
      tafas writes no configuration file and keeps no state between runs.
      Nothing else needs to be installed: it does not call ffmpeg, yt-dlp or any
      other program.
